text:
Set up the engagement

viewof fteCost   = Inputs.range([30000, 120000], {value: 60000, step: 1000, label: "Human FTE cost (£/yr, fully loaded)"})
viewof fteCount  = Inputs.range([1, 20],          {value: 3,     step: 1,    label: "FTEs replaced / augmented"})
viewof volume    = Inputs.range([100, 10000],     {value: 1000,  step: 100,  label: "Tasks delivered per month"})
viewof aiCost    = Inputs.range([0.1, 10],        {value: 2,     step: 0.1,  label: "AI cost to serve one task (£)"})
viewof value     = Inputs.range([5000, 500000],   {value: 50000, step: 5000, label: "Business value created per month (£)"})
viewof riskScore = Inputs.range([1, 10],          {value: 5,     step: 1,    label: "Risk score (1–10)"})
viewof autonomy  = Inputs.select(["L1", "L2", "L3", "L4", "L5"], {value: "L3", label: "Autonomy level"})
























































Fine-tune each model (optional)






viewof seatDiscount = Inputs.range([0.4, 0.7],   {value: 0.5,  step: 0.05, label: "M1 · seat discount vs human rate"})
viewof m2Margin     = Inputs.range([0.30, 0.50], {value: 0.40, step: 0.01, label: "M2 · target margin"})
viewof m2BaseFee    = Inputs.range([0, 5000],    {value: 500,  step: 100,  label: "M2 · monthly base fee (£)"})
viewof m3Margin     = Inputs.range([0.20, 0.70], {value: 0.40, step: 0.05, label: "M3 · target margin"})
viewof m4BaseFee    = Inputs.range([0, 30000],   {value: 8000, step: 500,  label: "M4 · base platform fee (£/mo)"})
viewof m4Share      = Inputs.range([0.01, 0.03], {value: 0.02, step: 0.005,label: "M4 · value share"})
viewof m5Share      = Inputs.range([0.02, 0.05], {value: 0.03, step: 0.005,label: "M5 · value share"})
viewof ceilMult     = Inputs.range([3, 5],       {value: 4,    step: 0.5,  label: "M5 · ceiling (× floor)"})





























































riskPremium = (score) =&gt; {
  const pts = [[1, 0.05], [3, 0.10], [6, 0.20], [8, 0.40], [10, 1.00]];
  if (score &lt;= 1) return 0.05;
  if (score &gt;= 10) return 1.00;
  for (let i = 0; i &lt; pts.length - 1; i++) {
    const [x0, y0] = pts[i], [x1, y1] = pts[i + 1];
    if (score &gt;= x0 && score &lt;= x1) return y0 + (y1 - y0) * (score - x0) / (x1 - x0);
  }
}
autonomyMod = (lvl) =&gt; (lvl === "L4" ? 1.20 : lvl === "L5" ? 1.40 : 1.00);
overlay = (base) =&gt; base * (1 + riskPremium(riskScore)) * autonomyMod(autonomy);

humanMonthly = fteCount * fteCost / 12;

prices = {
  const m1 = overlay(fteCount * (fteCost / 12) * seatDiscount);
  const m2 = overlay(m2BaseFee + volume * (aiCost / (1 - m2Margin)));
  const m3 = overlay(volume * (aiCost / (1 - m3Margin)));
  const m4 = overlay(m4BaseFee + value * m4Share);

  // M5 has its own floor/ceiling guardrails rather than the overlay
  const m4BaseOverlaid = overlay(m4BaseFee);
  const floor   = 0.8 * m4BaseOverlaid;
  const ceiling = ceilMult * floor;
  const m5raw   = value * m5Share;
  const m5      = Math.max(floor, Math.min(ceiling, m5raw));
  const m5bind  = m5raw &lt;= floor ? "floor binds" : m5raw &gt;= ceiling ? "ceiling binds" : "share applies";

  return [
    {model: "M1 Per Seat", price: m1, note: `${(seatDiscount*100).toFixed(0)}% of human rate`},
    {model: "M2 Usage",    price: m2, note: `${volume.toLocaleString()} tasks × unit price`},
    {model: "M3 Task",     price: m3, note: `${volume.toLocaleString()} tasks × task price`},
    {model: "M4 Hybrid",   price: m4, note: `base + ${(m4Share*100).toFixed(1)}% of value`},
    {model: "M5 Outcome",  price: m5, note: m5bind},
  ];
}

gbp = (x) =&gt; "£" + Math.round(x).toLocaleString("en-GB");
palette = ["#3DC7FF", "#0073E6", "#663894", "#AA4B8B", "#EF5E82"];

What the customer pays each month

Plot.plot({
  marginLeft: 70,
  marginBottom: 40,
  height: 380,
  x: {label: null, domain: prices.map(d =&gt; d.model)},
  y: {label: "↑ Monthly price to customer (£)", grid: true,
      tickFormat: (s) =&gt; "£" + (s / 1000) + "k"},
  color: {domain: prices.map(d =&gt; d.model), range: palette},
  marks: [
    Plot.barY(prices, {x: "model", y: "price", fill: "model",
      tip: {format: {y: gbp, fill: false}}}),
    Plot.text(prices, {x: "model", y: "price", text: (d) =&gt; gbp(d.price),
      dy: -8, fontWeight: "bold"}),
    Plot.ruleY([humanMonthly], {stroke: "#00005C", strokeWidth: 2, strokeDasharray: "5 4"}),
    Plot.text([`Human cost today  ·  ${gbp(humanMonthly)}/mo`],
      {frameAnchor: "top-right", dx: -6, dy: 8, fill: "#00005C", fontWeight: "bold"}),
    Plot.ruleY([0])
  ]
})







{
  const ps = prices.map(d =&gt; d.price);
  const lo = Math.min(...ps), hi = Math.max(...ps);
  const loModel = prices.find(d =&gt; d.price === lo).model;
  const hiModel = prices.find(d =&gt; d.price === hi).model;
  return html`&lt;div class="callout callout-style-default callout-tip"&gt;
    &lt;div class="callout-body" style="padding:0.8em 1em;"&gt;
      &lt;strong&gt;Same engagement, ${(hi / lo).toFixed(1)}× price spread.&lt;/strong&gt;
      From &lt;strong&gt;${gbp(lo)}/mo&lt;/strong&gt; (${loModel}) to &lt;strong&gt;${gbp(hi)}/mo&lt;/strong&gt; (${hiModel})
      — changing nothing but the pricing model. Annualised, that is
      ${gbp(lo * 12)} vs ${gbp(hi * 12)}.
    &lt;/div&gt;&lt;/div&gt;`;
}

Design the deal

viewof m4base   = Inputs.range([2000, 40000],   {value: 10000, step: 500,  label: "Equivalent M4 base fee (£/mo)"})
viewof floorPct = Inputs.range([0.6, 0.8],       {value: 0.8,   step: 0.05, label: "Floor (× M4 base)"})
viewof ceilMult = Inputs.range([3, 5],           {value: 4,     step: 0.5,  label: "Ceiling (× floor)"})
viewof valueType = Inputs.select([
  "Cost takeout (labour replaced)",
  "Cost avoidance (fraud, penalties)",
  "Revenue uplift (attributed)",
  "Risk reduction (liability avoided)"
], {label: "Value type", value: "Cost takeout (labour replaced)"})
viewof flatShare = Inputs.range([0.01, 0.06],    {value: 0.03,  step: 0.005, label: "Flat share %"})
viewof expValue  = Inputs.range([0, 5000000],    {value: 1000000, step: 50000, label: "Expected monthly value (£)"})












































viewof useTiered = Inputs.toggle({value: true, label: "Show tiered (Lehman) schedule"})












Tiered (Lehman) schedule — edit the steps






viewof t1rate = Inputs.range([0.01, 0.06], {value: 0.04,  step: 0.005, label: "Rate on first band"})
viewof t1cap  = Inputs.range([100000, 1000000], {value: 500000, step: 50000, label: "First band up to (£/mo)"})
viewof t2rate = Inputs.range([0.01, 0.05], {value: 0.025, step: 0.005, label: "Rate on second band"})
viewof t2cap  = Inputs.range([1000000, 3000000], {value: 2000000, step: 100000, label: "Second band up to (£/mo)"})
viewof t3rate = Inputs.range([0.005, 0.03],{value: 0.01,  step: 0.005, label: "Rate above second band"})








































chartMax = 5000000

floor   = m4base * floorPct
ceiling = ceilMult * floor

clamp = (x) =&gt; Math.max(floor, Math.min(ceiling, x))

flatRaw   = (v) =&gt; v * flatShare
tieredRaw = (v) =&gt; t1rate * Math.min(v, t1cap)
                 + t2rate * Math.max(0, Math.min(v, t2cap) - t1cap)
                 + t3rate * Math.max(0, v - t2cap)

flatFee   = (v) =&gt; clamp(flatRaw(v))
tieredFee = (v) =&gt; clamp(tieredRaw(v))

binding = (raw) =&gt; raw &lt;= floor ? "floor binds" : raw &gt;= ceiling ? "ceiling binds" : "share applies"

shareBand = ({
  "Cost takeout (labour replaced)":     "3–5%",
  "Cost avoidance (fraud, penalties)":  "2–4%",
  "Revenue uplift (attributed)":        "2–4%",
  "Risk reduction (liability avoided)": "2–5%"
})[valueType]

gbp  = (x) =&gt; "£" + Math.round(x).toLocaleString("en-GB")
gbpC = (x) =&gt; x &gt;= 1e6 ? "£" + (x/1e6).toFixed(x &gt;= 1e7 ? 0 : 2) + "M"
            : x &gt;= 1e3 ? "£" + Math.round(x/1e3) + "k" : "£" + Math.round(x)
axisFmt = (s) =&gt; s &gt;= 1e6 ? "£" + (s/1e6) + "M" : s &gt;= 1e3 ? "£" + (s/1e3) + "k" : "£" + s
pct  = (x) =&gt; (100*x).toFixed(1) + "%"

curve = {
  const n = 240, a = [];
  for (let i = 0; i &lt;= n; i++) {
    const v = chartMax * i / n;
    a.push({v, fee: flatFee(v), series: "Flat share"});
    if (useTiered) a.push({v, fee: tieredFee(v), series: "Tiered (Lehman)"});
  }
  return a;
}

effCurve = {
  const n = 240, a = [];
  for (let i = 1; i &lt;= n; i++) {
    const v = chartMax * i / n;
    a.push({v, eff: 100 * flatFee(v) / v, series: "Flat share"});
    if (useTiered) a.push({v, eff: 100 * tieredFee(v) / v, series: "Tiered (Lehman)"});
  }
  return a;
}

palette = ({"Flat share": "#C0392B", "Tiered (Lehman)": "#4AA82D"})

opPoints = useTiered
  ? [{v: expValue, fee: flatFee(expValue), series: "Flat share"},
     {v: expValue, fee: tieredFee(expValue), series: "Tiered (Lehman)"}]
  : [{v: expValue, fee: flatFee(expValue), series: "Flat share"}]
































































































































html`&lt;div style="font-size:.9em;color:#555;margin:-.3em 0 .4em;"&gt;
  Recommended share for &lt;b&gt;${valueType}&lt;/b&gt;: &lt;b&gt;${shareBand}&lt;/b&gt;.
  Floor = ${gbp(floor)}/mo · Ceiling = ${gbp(ceiling)}/mo.&lt;/div&gt;`

At your expected value

{
  const ev = expValue;
  const card = (name, colour, fee, raw) =&gt; `
    &lt;div style="flex:1;background:${colour};color:#fff;border-radius:10px;padding:.85em 1.1em;"&gt;
      &lt;div style="font-size:.78em;text-transform:uppercase;letter-spacing:.05em;opacity:.9;"&gt;${name}&lt;/div&gt;
      &lt;div style="font-size:1.7em;font-weight:800;"&gt;${gbp(fee)}&lt;span style="font-size:.5em;font-weight:600;"&gt; / mo&lt;/span&gt;&lt;/div&gt;
      &lt;div style="font-size:.9em;margin-top:.3em;"&gt;
        ${binding(raw)} · effective ${pct(fee/ev)} · ${gbp(fee*12)}/yr
      &lt;/div&gt;
    &lt;/div&gt;`;
  const flat = card("Flat share", "#C0392B", flatFee(ev), flatRaw(ev));
  const tier = useTiered ? card("Tiered (Lehman)", "#4AA82D", tieredFee(ev), tieredRaw(ev)) : "";
  return html([`&lt;div style="display:flex;gap:.8em;"&gt;${flat}${tier}&lt;/div&gt;`]);
}







{
  const ev = expValue, ff = flatFee(ev), tf = tieredFee(ev), fr = flatRaw(ev);
  let level, msg;
  if (fr &gt;= ceiling) {
    level = "warn";
    msg = `At ${gbpC(ev)} the flat share would blow through the ceiling — the cap is doing all the work, and the headline % will feel unfair to the customer. A tiered schedule lands more naturally.`;
  } else if (useTiered && ff &gt; 1.25 * tf) {
    level = "warn";
    msg = `The flat fee (${gbpC(ff)}) is ${(ff/tf).toFixed(1)}× the tiered fee here — high renegotiation risk. At scale a flat % reads as a windfall; the tiered schedule defuses it.`;
  } else {
    level = "ok";
    msg = `At ${gbpC(ev)} the schedules are close and either is defensible — but the gap widens as value grows. Lock the tiered steps in now.`;
  }
  const c = level === "warn" ? "#E8830C" : "#4AA82D";
  return html`&lt;div style="border-left:5px solid ${c};background:${c}14;padding:.7em 1em;border-radius:8px;font-size:.98em;"&gt;
    &lt;b style="color:${c};"&gt;${level === "warn" ? "⚠ Renegotiation risk" : "✓ Balanced"}&lt;/b&gt; — ${msg}&lt;/div&gt;`;
}

Who keeps the value?

{
  const ev = expValue;
  const fee = useTiered ? tieredFee(ev) : flatFee(ev);
  const keep = Math.max(0, ev - fee);
  const fp = 100 * fee / ev, kp = 100 * keep / ev;
  return html`&lt;div&gt;
    &lt;div style="display:flex;height:34px;border-radius:7px;overflow:hidden;font-size:.82em;color:#fff;font-weight:700;"&gt;
      &lt;div style="width:${fp}%;background:#4AA82D;display:flex;align-items:center;justify-content:center;min-width:fit-content;padding:0 .4em;"&gt;
        Atos ${pct(fee/ev)}&lt;/div&gt;
      &lt;div style="width:${kp}%;background:#0073E6;display:flex;align-items:center;justify-content:center;padding:0 .4em;"&gt;
        Customer keeps ${pct(keep/ev)}&lt;/div&gt;
    &lt;/div&gt;
    &lt;div style="font-size:.9em;color:#555;margin-top:.4em;"&gt;
      Atos captures &lt;b&gt;${gbp(fee)}/mo&lt;/b&gt;; the customer retains &lt;b&gt;${gbp(keep)}/mo&lt;/b&gt; of the value created.
      Growing the pool beats grabbing a bigger slice — 3% of £10M beats 15% of £1M.&lt;/div&gt;
  &lt;/div&gt;`;
}

This walks the same decision tree as the CoE Model Selection Guide. Click your way through — each answer reveals the next question, and your recommendation appears at the end. Click any crumb in the trail to jump back and explore a different branch.

